CREATE TABLE category(id BIGINT PRIMARY KEY AUTO_INCREMENT,parent_id BIGINT NULL,name VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(parent_id) REFERENCES category(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE brand(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE specification(id BIGINT PRIMARY KEY AUTO_INCREMENT,name VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE specification_value(id BIGINT PRIMARY KEY AUTO_INCREMENT,specification_id BIGINT NOT NULL,name VARCHAR(64) NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(specification_id) REFERENCES specification(id),UNIQUE(specification_id,name)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_spu(id BIGINT PRIMARY KEY AUTO_INCREMENT,category_id BIGINT NOT NULL,brand_id BIGINT NULL,title VARCHAR(200) NOT NULL,on_sale BOOLEAN NOT NULL DEFAULT FALSE,sale_version BIGINT NOT NULL DEFAULT 1,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),updated_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(category_id) REFERENCES category(id),FOREIGN KEY(brand_id) REFERENCES brand(id),INDEX idx_product_sale(on_sale,category_id,id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_sku(id BIGINT PRIMARY KEY AUTO_INCREMENT,spu_id BIGINT NOT NULL,spec_key VARCHAR(340) NOT NULL,specs VARCHAR(2048) NOT NULL,price_fen BIGINT NOT NULL,enabled BOOLEAN NOT NULL DEFAULT TRUE,FOREIGN KEY(spu_id) REFERENCES product_spu(id),UNIQUE(spu_id,spec_key),CHECK(price_fen>=0)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_image(id BIGINT PRIMARY KEY AUTO_INCREMENT,spu_id BIGINT NOT NULL,url VARCHAR(2048) NOT NULL,position INT NOT NULL,FOREIGN KEY(spu_id) REFERENCES product_spu(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE sku_spec_value(id BIGINT PRIMARY KEY AUTO_INCREMENT,sku_id BIGINT NOT NULL,value_id BIGINT NOT NULL,FOREIGN KEY(sku_id) REFERENCES product_sku(id),FOREIGN KEY(value_id) REFERENCES specification_value(id),UNIQUE(sku_id,value_id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
CREATE TABLE product_price_log(id BIGINT PRIMARY KEY AUTO_INCREMENT,sku_id BIGINT NOT NULL,old_price_fen BIGINT NULL,new_price_fen BIGINT NOT NULL,created_at DATETIME(6) NOT NULL DEFAULT CURRENT_TIMESTAMP(6),FOREIGN KEY(sku_id) REFERENCES product_sku(id)) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4;
